"""
Intelligent Maintenance Recommendation System for MaintenAI.
Combines machine learning failure probabilities with transparent, rule-based
mechanical and thermodynamic heuristics to prescribe targeted maintenance actions.
"""

from typing import Dict, Any, List
import numpy as np

LEGAL_DISCLAIMER = (
    "DISCLAIMER: Recommendations generated by MaintenAI are AI-assisted decision-support suggestions "
    "based on statistical models and heuristic thresholds. They are NOT certified industrial safety "
    "or statutory engineering instructions. All actions must be validated by licensed technicians."
)


def evaluate_maintenance_rules(
    sensor_data: Dict[str, Any],
    failure_probability: float,
    predicted_status: str,
    risk_category: str,
    failure_types: List[str] = None,
) -> Dict[str, Any]:
    """
    Evaluates physical sensor parameters, ML probability, and predicted failure modes
    to formulate actionable maintenance recommendations with domain engineering rationale.
    Provides subsystem-level diagnostic cards that update dynamically with every sensor change.
    """
    air_temp = float(sensor_data.get("Air temperature", 300.0))
    proc_temp = float(sensor_data.get("Process temperature", 310.0))
    speed = float(sensor_data.get("Rotational speed", 1500.0))
    torque = float(sensor_data.get("Torque", 40.0))
    tool_wear = float(sensor_data.get("Tool wear", 100.0))
    machine_type = str(sensor_data.get("Type", "L"))

    temp_diff = proc_temp - air_temp
    power_kw = (torque * speed * 2 * np.pi) / (60 * 1000)
    strain = torque * tool_wear
    strain_limit = {"L": 11000, "M": 12000, "H": 13000}.get(machine_type, 11000)

    abnormal_parameters = []
    recommendations = []
    reasons = []
    priority_level = "Normal"
    subsystem_diagnostics = []

    # -------------------------------------------------------------
    # 1. TOOL WEAR & CUTTER LIFESPAN SUBSYSTEM
    # -------------------------------------------------------------
    if tool_wear >= 200:
        param_msg = f"Tool wear critical ({tool_wear:.0f} min >= 200 min limit)"
        act_msg = "Immediate cutting tool replacement and tool holder inspection."
        reas_msg = (
            f"Cumulative tool wear has reached {tool_wear:.0f} min (exceeds 200 min maximum lifespan). "
            "Severe micro-chipping and flank wear elevate friction, risking cutter rupture and workpiece damage."
        )
        abnormal_parameters.append(param_msg)
        recommendations.append(act_msg)
        reasons.append(reas_msg)
        priority_level = "High"
        subsystem_diagnostics.append({
            "subsystem": "Cutting Tool & Spindle Assembly",
            "parameter": f"Tool Wear: {tool_wear:.0f} min",
            "status": "CRITICAL WEAR",
            "badge_type": "danger",
            "reason": reas_msg,
            "action": act_msg,
        })
    elif tool_wear >= 160:
        param_msg = f"Tool wear elevated ({tool_wear:.0f} min)"
        act_msg = "Schedule proactive tool replacement during next planned work shift."
        reas_msg = (
            f"Tool wear is at {tool_wear:.0f} min (75%+ of calibrated operational lifespan). "
            "Cutting edge dulling is initiating increased vibration and heat generation."
        )
        abnormal_parameters.append(param_msg)
        recommendations.append(act_msg)
        reasons.append(reas_msg)
        if priority_level == "Normal":
            priority_level = "Medium"
        subsystem_diagnostics.append({
            "subsystem": "Cutting Tool & Spindle Assembly",
            "parameter": f"Tool Wear: {tool_wear:.0f} min",
            "status": "ELEVATED WEAR",
            "badge_type": "warning",
            "reason": reas_msg,
            "action": act_msg,
        })
    else:
        subsystem_diagnostics.append({
            "subsystem": "Cutting Tool & Spindle Assembly",
            "parameter": f"Tool Wear: {tool_wear:.0f} min",
            "status": "NOMINAL",
            "badge_type": "healthy",
            "reason": f"Tool wear ({tool_wear:.0f} min) is within safe operational limits (< 160 min). Cutting edge remains sharp.",
            "action": "Maintain scheduled lubrication and standard machining cycle.",
        })

    # -------------------------------------------------------------
    # 2. THERMODYNAMICS & HEAT DISSIPATION SUBSYSTEM
    # -------------------------------------------------------------
    if temp_diff < 8.6 and speed < 1380:
        param_msg = f"Heat dissipation failure condition (Delta T {temp_diff:.1f} K < 8.6 K at {speed:.0f} rpm)"
        act_msg = "Inspect forced-air cooling fans, coolant circulation pump, and heat exchanger fins for fouling."
        reas_msg = (
            f"Temperature delta between process ({proc_temp:.1f} K) and ambient ({air_temp:.1f} K) is only {temp_diff:.1f} K (< 8.6 K) "
            f"combined with low convective airflow ({speed:.0f} rpm < 1380 rpm), preventing thermodynamic heat rejection."
        )
        abnormal_parameters.append(param_msg)
        recommendations.append(act_msg)
        reasons.append(reas_msg)
        priority_level = "High"
        subsystem_diagnostics.append({
            "subsystem": "Thermodynamics & Cooling Circuit",
            "parameter": f"Temp Delta: {temp_diff:.1f} K (Speed: {speed:.0f} rpm)",
            "status": "HEAT DISSIPATION FAILURE RISK",
            "badge_type": "danger",
            "reason": reas_msg,
            "action": act_msg,
        })
    elif temp_diff > 12.5:
        param_msg = f"Elevated thermal gradient (Delta T {temp_diff:.1f} K > 12.5 K)"
        act_msg = "Verify coolant flow rate and inspect thermal sensors for calibration drift."
        reas_msg = f"Unusually high temperature rise ({temp_diff:.1f} K) between ambient and process chamber indicates localized friction."
        abnormal_parameters.append(param_msg)
        recommendations.append(act_msg)
        reasons.append(reas_msg)
        subsystem_diagnostics.append({
            "subsystem": "Thermodynamics & Cooling Circuit",
            "parameter": f"Temp Delta: {temp_diff:.1f} K",
            "status": "THERMAL ELEVATION",
            "badge_type": "warning",
            "reason": reas_msg,
            "action": act_msg,
        })
    else:
        subsystem_diagnostics.append({
            "subsystem": "Thermodynamics & Cooling Circuit",
            "parameter": f"Temp Delta: {temp_diff:.1f} K (Air: {air_temp:.1f} K, Proc: {proc_temp:.1f} K)",
            "status": "NOMINAL",
            "badge_type": "healthy",
            "reason": f"Thermodynamic gradient ({temp_diff:.1f} K) is within nominal convective dissipation bounds (8.6 K - 12.5 K).",
            "action": "Maintain normal continuous cooling and ambient ventilation.",
        })

    # -------------------------------------------------------------
    # 3. SPINDLE POWER & DRIVE MOTOR SUBSYSTEM
    # -------------------------------------------------------------
    if power_kw < 3.5:
        param_msg = f"Spindle mechanical power deficit ({power_kw:.2f} kW < 3.5 kW limit)"
        act_msg = "Inspect variable frequency drive (VFD), electrical inverter, and spindle drive belt for slip."
        reas_msg = f"Mechanical delivered power ({power_kw:.2f} kW) drops below standard cutting envelope (3.5 kW - 9.0 kW), risking stall."
        abnormal_parameters.append(param_msg)
        recommendations.append(act_msg)
        reasons.append(reas_msg)
        priority_level = "High"
        subsystem_diagnostics.append({
            "subsystem": "Spindle Power & Inverter Drive",
            "parameter": f"Delivered Power: {power_kw:.2f} kW",
            "status": "POWER DEFICIT",
            "badge_type": "danger",
            "reason": reas_msg,
            "action": act_msg,
        })
    elif power_kw > 9.0:
        param_msg = f"Spindle mechanical power surge ({power_kw:.2f} kW > 9.0 kW limit)"
        act_msg = "Check motor overload relay, examine cutter engagement depth, and inspect power inverter."
        reas_msg = f"Mechanical power demand ({power_kw:.2f} kW) exceeds safe motor ratings (9.0 kW), risking electrical breaker trip."
        abnormal_parameters.append(param_msg)
        recommendations.append(act_msg)
        reasons.append(reas_msg)
        priority_level = "High"
        subsystem_diagnostics.append({
            "subsystem": "Spindle Power & Inverter Drive",
            "parameter": f"Delivered Power: {power_kw:.2f} kW",
            "status": "POWER SURGE / OVERLOAD",
            "badge_type": "danger",
            "reason": reas_msg,
            "action": act_msg,
        })
    else:
        subsystem_diagnostics.append({
            "subsystem": "Spindle Power & Inverter Drive",
            "parameter": f"Delivered Power: {power_kw:.2f} kW",
            "status": "NOMINAL",
            "badge_type": "healthy",
            "reason": f"Spindle power delivery ({power_kw:.2f} kW) operates comfortably inside stable bounds [3.5 kW, 9.0 kW].",
            "action": "Routine electrical inspection on scheduled maintenance cycle.",
        })

    # -------------------------------------------------------------
    # 4. MECHANICAL OVERSTRAIN & TORQUE SUBSYSTEM
    # -------------------------------------------------------------
    if strain > strain_limit:
        param_msg = f"Overstrain index critical ({strain:.0f} Nm*min exceeds {strain_limit} limit for Type {machine_type})"
        act_msg = "Perform mechanical inspection of spindle bearings, drive shaft alignment, and reduce feed rate."
        reas_msg = (
            f"Combined structural stress (Torque {torque:.1f} Nm x Tool Wear {tool_wear:.0f} min = {strain:.0f} Nm*min) "
            f"exceeds mechanical fatigue limit ({strain_limit} for variant {machine_type}), risking spindle fracture."
        )
        abnormal_parameters.append(param_msg)
        recommendations.append(act_msg)
        reasons.append(reas_msg)
        priority_level = "Critical"
        subsystem_diagnostics.append({
            "subsystem": "Mechanical Transmission & Strain",
            "parameter": f"Strain: {strain:.0f} Nm*min (Limit: {strain_limit})",
            "status": "OVERSTRAIN HAZARD",
            "badge_type": "danger",
            "reason": reas_msg,
            "action": act_msg,
        })
    elif torque > 60.0:
        param_msg = f"Elevated mechanical torque ({torque:.1f} Nm > 60.0 Nm)"
        act_msg = "Verify workpiece clamping rigidity, lubrication, and reduce depth of cut."
        reas_msg = f"Torque load ({torque:.1f} Nm) is abnormally high, indicating excessive cutting resistance."
        abnormal_parameters.append(param_msg)
        recommendations.append(act_msg)
        reasons.append(reas_msg)
        if priority_level != "Critical":
            priority_level = "High"
        subsystem_diagnostics.append({
            "subsystem": "Mechanical Transmission & Strain",
            "parameter": f"Spindle Torque: {torque:.1f} Nm",
            "status": "HIGH TORQUE LOAD",
            "badge_type": "warning",
            "reason": reas_msg,
            "action": act_msg,
        })
    else:
        subsystem_diagnostics.append({
            "subsystem": "Mechanical Transmission & Strain",
            "parameter": f"Torque: {torque:.1f} Nm (Strain: {strain:.0f} / {strain_limit})",
            "status": "NOMINAL",
            "badge_type": "healthy",
            "reason": f"Torque and cumulative strain ({strain:.0f} Nm*min) are well below structural limits ({strain_limit} Nm*min).",
            "action": "Maintain normal feed and speed parameters.",
        })

    # -------------------------------------------------------------
    # 5. ROTATIONAL SPEED DYNAMICS
    # -------------------------------------------------------------
    if speed < 1250 or speed > 2400:
        param_msg = f"Rotational speed anomaly ({speed:.0f} rpm outside [1250, 2400] rpm)"
        act_msg = "Calibrate tachometer / rotary encoder and check motor drive belt tension."
        reas_msg = f"Spindle velocity ({speed:.0f} rpm) deviates from the standard operational band."
        abnormal_parameters.append(param_msg)
        recommendations.append(act_msg)
        reasons.append(reas_msg)
        subsystem_diagnostics.append({
            "subsystem": "Kinematic Speed Regulation",
            "parameter": f"Rotational Speed: {speed:.0f} rpm",
            "status": "SPEED ANOMALY",
            "badge_type": "warning",
            "reason": reas_msg,
            "action": act_msg,
        })
    else:
        subsystem_diagnostics.append({
            "subsystem": "Kinematic Speed Regulation",
            "parameter": f"Rotational Speed: {speed:.0f} rpm",
            "status": "NOMINAL",
            "badge_type": "healthy",
            "reason": f"Spindle speed ({speed:.0f} rpm) is within nominal operating tolerances.",
            "action": "No kinetic intervention required.",
        })

    # -------------------------------------------------------------
    # 6. ML PREDICTIVE FAILURE PROBABILITY OVERLAY
    # -------------------------------------------------------------
    if failure_probability >= 0.65 or predicted_status == "Potential Failure":
        param_msg = f"ML Failure Probability High ({failure_probability * 100:.1f}%)"
        act_msg = "PRIORITY DISPATCH: Schedule immediate diagnostic shutdown and comprehensive multi-point maintenance audit."
        reas_msg = (
            f"Ensemble machine learning model predicts a {failure_probability * 100:.1f}% probability of imminent failure "
            "based on combined multivariate sensor signatures."
        )
        abnormal_parameters.insert(0, param_msg)
        recommendations.insert(0, act_msg)
        reasons.insert(0, reas_msg)
        priority_level = "Critical"
    elif failure_probability >= 0.25:
        if priority_level == "Normal":
            priority_level = "Medium"
        abnormal_parameters.append(f"ML Failure Probability Moderate ({failure_probability * 100:.1f}%)")
        recommendations.append("Increase condition-monitoring telemetry frequency and log daily sensor telemetry.")
        reasons.append(f"Machine is operating in the elevated risk tier (Failure Probability: {failure_probability * 100:.1f}%).")

    # Fallback if all sensors are nominal
    if not recommendations:
        abnormal_parameters = ["None. All operational sensors within nominal baselines."]
        recommendations = [
            "Maintain standard routine preventive maintenance interval and scheduled lubrication."
        ]
        reasons = [
            "All thermal, kinetic, power, and wear parameters operate comfortably within calibrated safe tolerance limits."
        ]
        priority_level = "Low"

    return {
        "abnormal_parameters": abnormal_parameters,
        "predicted_status": predicted_status,
        "failure_probability_pct": round(failure_probability * 100, 2),
        "risk_category": risk_category,
        "priority_level": priority_level,
        "recommended_actions": recommendations,
        "engineering_reasons": reasons,
        "subsystem_diagnostics": subsystem_diagnostics,
        "failure_types_considered": failure_types or [],
        "disclaimer": LEGAL_DISCLAIMER,
    }
